import { forwardRef, type HTMLAttributes } from "react";
import { cn } from "../lib/utils";

export type IconName =
  // bungalow-icons:start (generated by scripts/icon-font/generate.py - do not hand-edit)
  | "banknote"
  | "calendar"
  | "calendar-alt"
  | "clock"
  | "coin"
  | "compass"
  | "credit-card"
  | "credit-card-alt"
  | "date"
  | "document"
  | "edit"
  | "folder-open"
  | "forward"
  | "home"
  | "jump-back-15s"
  | "jump-forward-15s"
  | "like"
  | "like-fill"
  | "minus"
  | "moon"
  | "pause"
  | "play"
  | "plus"
  | "record"
  | "recycle-bin"
  | "repeat"
  | "rewind"
  | "settings"
  | "skip-to-next"
  | "skip-to-prev"
  | "stop"
  | "three-dots-h"
  | "three-dots-v"
  | "timer"
  | "user"
  | "users"
  // bungalow-icons:end
  ;

export interface IconProps extends HTMLAttributes<HTMLSpanElement> {
  name: IconName;
}

export const Icon = forwardRef<HTMLSpanElement, IconProps>(function Icon({ name, className, ...props }, ref) {
  return <span ref={ref} aria-hidden="true" className={cn(`bungalow-icon-${name}`, className)} {...props} />;
});
